// HasDrinks applies the HasEdge predicate on the "drinks" edge.
func HasDrinks() predicate.Brand {
	return predicate.Brand(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, DrinksTable, DrinksColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDrinksWith applies the HasEdge predicate on the "drinks" edge with a given conditions (other predicates).
func HasDrinksWith(preds ...predicate.Drink) predicate.Brand {
	return predicate.Brand(func(s *sql.Selector) {
		step := newDrinksStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Brand) predicate.Brand {
	return predicate.Brand(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Brand) predicate.Brand {
	return predicate.Brand(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Brand) predicate.Brand {
	return predicate.Brand(sql.NotPredicates(p))
}
